'use client';

import { ArrowLeft, Printer } from 'lucide-react';
import Link from 'next/link';
import { useParams } from 'next/navigation';
import { useTranslation } from 'react-i18next';
import type { ReportCard } from '@edventure/contracts';
import { Button } from '@/components/ui/button';
import { ErrorState, LoadingBlock } from '@/components/ui/states';
import { formatDate, formatNumber, formatPercent } from '@/lib/format';
import { useApi, useLang } from '@/lib/hooks';

/** Printable report card. The same data backs the PDF generated by the report worker. */
export default function ReportCardPage() {
  const { id, studentId } = useParams<{ id: string; studentId: string }>();
  const { t } = useTranslation();
  const lang = useLang();
  const q = useApi<ReportCard>(['report-card', id, studentId], `/results/${id}/report-cards/${studentId}`);
  if (q.isLoading) return <LoadingBlock />;
  if (q.error || !q.data) return <ErrorState error={q.error} />;
  const c = q.data;
  const r = c.result;
  const d = c.displayDecimals;
  const name = lang === 'ur' && c.student.displayNameUr ? c.student.displayNameUr : c.student.displayName;
  const outcomeClass = r.outcome === 'pass' ? 'text-success-fg' : r.outcome === 'fail' ? 'text-danger-fg' : 'text-warning-fg';

  return (
    <>
      <div className="no-print mb-4 flex items-center justify-between">
        <Link href={`/admin/results/${id}`} className="inline-flex items-center gap-1 text-[13px] text-muted hover:text-ink"><ArrowLeft size={14} className="rtl:rotate-180" /> {t('nav.results')}</Link>
        <Button variant="primary" icon={<Printer size={16} />} onClick={() => window.print()}>{t('common.print')}</Button>
      </div>
      <article className="mx-auto max-w-3xl rounded-[var(--radius-card)] border border-line bg-surface p-8 print:max-w-none print:border-0 print:p-0">
        <header className="flex items-start justify-between gap-6 border-b-2 border-accent-700 pb-4">
          <div>
            <h1 className="text-xl font-semibold text-accent-800">{lang === 'ur' && c.school.nameUr ? c.school.nameUr : c.school.name}</h1>
            <p className="text-[13px] text-muted">{c.school.code} · {c.academicYearCode}</p>
          </div>
          <div className="text-end">
            <p className="text-lg font-semibold">{t('exams.reportCard')}</p>
            <p className="text-[13px] text-muted">{c.examCycleName}</p>
          </div>
        </header>
        <dl className="grid grid-cols-2 gap-x-8 gap-y-2 py-4 text-sm sm:grid-cols-4">
          <div><dt className="text-[12px] text-muted">{t('web.common.student')}</dt><dd className="font-semibold">{name}</dd></div>
          <div><dt className="text-[12px] text-muted">{t('web.people.admissionNumber')}</dt><dd className="font-medium">{c.student.admissionNumber}</dd></div>
          <div><dt className="text-[12px] text-muted">{t('web.common.class')}</dt><dd className="font-medium">{c.gradeName}{c.sectionName ? ` ${c.sectionName}` : ''}</dd></div>
          <div><dt className="text-[12px] text-muted">{t('web.reportCard.issued')}</dt><dd className="font-medium">{formatDate(c.publishedAt, lang)}{c.revision > 1 ? ` · ${t('web.results.revisionN', { n: c.revision })}` : ''}</dd></div>
        </dl>
        <table className="w-full border-collapse text-sm">
          <thead>
            <tr className="bg-accent-50 text-accent-800">
              <th className="border border-line px-3 py-2 text-start">{t('web.common.subject')}</th>
              <th className="border border-line px-3 py-2 text-end">{t('exams.maxMarks')}</th>
              <th className="border border-line px-3 py-2 text-end">{t('web.reportCard.obtained')}</th>
              <th className="border border-line px-3 py-2 text-end">{t('exams.percentage')}</th>
              <th className="border border-line px-3 py-2 text-center">{t('exams.grade')}</th>
              <th className="border border-line px-3 py-2 text-start">{t('web.results.outcome')}</th>
            </tr>
          </thead>
          <tbody>
            {r.subjects.map((s) => (
              <tr key={s.courseOfferingId}>
                <td className="border border-line px-3 py-1.5">{lang === 'ur' && s.subjectNameUr ? s.subjectNameUr : s.subjectName}</td>
                <td className="tabular border border-line px-3 py-1.5 text-end">{formatNumber(s.maxMarks)}</td>
                <td className="tabular border border-line px-3 py-1.5 text-end">{formatNumber(s.obtainedMarks)}</td>
                <td className="tabular border border-line px-3 py-1.5 text-end">{formatPercent(s.percentage, d)}</td>
                <td className="border border-line px-3 py-1.5 text-center font-semibold"><bdi dir="ltr">{s.gradeLabel ?? '—'}</bdi></td>
                <td className="border border-line px-3 py-1.5">{t(`web.results.subjectOutcome.${s.outcome}`)}</td>
              </tr>
            ))}
            <tr className="bg-sunken font-semibold">
              <td className="border border-line px-3 py-2">{t('web.common.total')}</td>
              <td className="tabular border border-line px-3 py-2 text-end">{formatNumber(r.totalMarks)}</td>
              <td className="tabular border border-line px-3 py-2 text-end">{formatNumber(r.obtainedMarks)}</td>
              <td className="tabular border border-line px-3 py-2 text-end">{formatPercent(r.percentage, d)}</td>
              <td className="border border-line px-3 py-2 text-center"><bdi dir="ltr">{r.gradeLabel ?? '—'}</bdi></td>
              <td className={`border border-line px-3 py-2 ${outcomeClass}`}>{t(`exams.${r.outcome}`)}</td>
            </tr>
          </tbody>
        </table>
        <div className="mt-5 grid gap-4 sm:grid-cols-2">
          <section className="rounded-lg border border-line p-3">
            <h2 className="mb-1 text-[13px] font-semibold">{t('nav.attendance')}</h2>
            <p className="text-sm">{t('attendance.summary', c.attendance)}</p>
            <p className="text-[13px] text-muted">{t('attendance.rate')}: {c.attendance.rate ? formatPercent(c.attendance.rate) : t('common.noData')}</p>
          </section>
          <section className="rounded-lg border border-line p-3">
            <h2 className="mb-1 text-[13px] font-semibold">{t('web.results.remarks')}</h2>
            <p className="text-sm">{r.remarks ?? '—'}</p>
            {r.gpa && <p className="mt-1 text-[13px] text-muted">GPA: {r.gpa}</p>}
          </section>
        </div>
        <footer className="mt-12 grid grid-cols-2 gap-12 text-[13px] text-muted">
          <div className="border-t border-line-strong pt-1">{t('roles.classTeacher')}</div>
          <div className="border-t border-line-strong pt-1 text-end">{t('web.reportCard.principal')}</div>
        </footer>
      </article>
    </>
  );
}
